#[test]
fn the_neon_forms_agree_with_qemu() {
    // Every disagreement at once: one wrong operation usually shows in all
    // of its sizes, and the pattern across them says more than the first.
    let mut wrong = Vec::new();
    for &(insn, before, after) in CASES {
        let mut cpu = cpu();
        let code: Vec<u32> = LOAD
            .into_iter()
            .chain(insn.iter().copied())
            .chain(STORE)
            .collect();
        load(&mut cpu, &code);
        for (i, &word) in before.iter().enumerate() {
            cpu.mem.write_u32(SCRATCH + 4 * i as u32, word).unwrap();
        }
        if let Err(error) = cpu.run(code.len() as u64 + 1) {
            wrong.push(format!("{insn:08x?}: {error}"));
            continue;
        }
        let got: Vec<u32> = (0..13)
            .map(|i| cpu.mem.read_u32(SCRATCH + 0x100 + 4 * i).unwrap())
            .collect();
        if got != after {
            wrong.push(format!(
                "{insn:08x?} on {before:08x?}: got q10 and r2 {:08x?}, qemu {:08x?}",
                &got[8..],
                &after[8..]
            ));
        }
    }
    assert!(
        wrong.is_empty(),
        "{} disagree:\n{}",
        wrong.len(),
        wrong.join("\n")
    );
}
